"use client";
import { useState } from "react";

export default async function LandingPageAnime() {
  const [listCount, setListCount] = useState(0);
  const animeList = new Map<number, Object>();
  // for (let id = 1; id <= 10; id++) {
  const fetchedData = await fetch(`https://api.jikan.moe/v4/anime/${1}`);
  const data = await fetchedData.json();
  animeList.set(1, data);
  // }

  setListCount(animeList.size);

  return (
    <>
      <p>{listCount}</p>
    </>
  );
}
